import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.CWWEQfK7.js";const p=JSON.parse('{"title":"Understand features before settings","description":"Map analysis, retrieval, chat, automation, and access control to the services and settings each feature requires.","frontmatter":{"page_id":"configuration-features","title":"Understand features before settings","description":"Map analysis, retrieval, chat, automation, and access control to the services and settings each feature requires."},"headers":[],"relativePath":"en/configuration/index.md","filePath":"en/configuration/index.md","lastUpdated":1786290726000}'),s={name:"en/configuration/index.md"};function i(o,e,d,c,l,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="understand-features-before-settings" tabindex="-1">Understand features before settings <a class="header-anchor" href="#understand-features-before-settings" aria-label="Permalink to &quot;Understand features before settings&quot;">​</a></h1><p>Ershu configuration spans Core, API, Worker, MCP, and frontend. Starting from the feature you need is usually a faster way to find missing settings than filling in environment variables one by one.</p><h2 id="three-kinds-of-settings" tabindex="-1">Three kinds of settings <a class="header-anchor" href="#three-kinds-of-settings" aria-label="Permalink to &quot;Three kinds of settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kind</th><th>Typical examples</th><th>When read</th><th>How to change it</th></tr></thead><tbody><tr><td>Startup requirement</td><td>Database URL, encryption keys, bind address</td><td>Process startup</td><td>Environment or env file; usually requires a restart</td></tr><tr><td>Runtime-managed setting</td><td>Worker concurrency, budgets, retrieval limits, dependency sources</td><td>While services are running</td><td>Admin UI or API; a database value can override startup configuration</td></tr><tr><td>Frontend build setting</td><td>API base URL, development proxy</td><td>Frontend startup or build</td><td><code>VITE_</code> environment variable; rebuild after a change</td></tr></tbody></table><p>Core is a shared package, not a separate process. API, Worker, and MCP all use parts of Core&#39;s database, security, and retrieval configuration. Identical setting names do not make process environments shared, so each deployed process still needs the values it consumes.</p><h2 id="features-and-their-dependencies" tabindex="-1">Features and their dependencies <a class="header-anchor" href="#features-and-their-dependencies" aria-label="Permalink to &quot;Features and their dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Modules involved</th><th>Required conditions</th><th>Verification</th></tr></thead><tbody><tr><td>Login and web administration</td><td>API, frontend, Core</td><td>PostgreSQL, session and OPAQUE keys, correct origin policy</td><td>Register the first admin and retrieve the current user</td></tr><tr><td>Repository and project management</td><td>API, frontend, Core</td><td>Project access; provider credentials for remote repositories</td><td>Repository validation succeeds and the project shows the repository</td></tr><tr><td>Full and incremental analysis</td><td>API, Worker, Core</td><td>PostgreSQL, a running Worker, readable repositories; generated docs also need a model channel</td><td>A run moves from queued to running and reaches an explicit outcome</td></tr><tr><td>Lexical search</td><td>API, Worker, Core, frontend</td><td>A completed code index</td><td>Results include repository, path, and source location</td></tr><tr><td>Semantic search</td><td>API, Worker, Core, frontend</td><td>Milvus, embedding configuration, and a completed search index</td><td>The response reports semantic or hybrid as the effective mode</td></tr><tr><td>Project documentation and chat</td><td>API, Worker, Core, frontend</td><td>An enabled model channel and completed documents</td><td>A document opens and chat returns inspectable citations</td></tr><tr><td>MCP queries</td><td>MCP, Core</td><td>PostgreSQL, MCP authentication, and a project-scoped key</td><td>A client lists permitted projects and reads context</td></tr><tr><td>Scheduled and webhook updates</td><td>API, Worker, Core</td><td>Poller or webhook signing key, plus a running Worker</td><td>A new run records its trigger and target revision</td></tr></tbody></table><h2 id="what-analysis-requires" tabindex="-1">What analysis requires <a class="header-anchor" href="#what-analysis-requires" aria-label="Permalink to &quot;What analysis requires&quot;">​</a></h2><p>The API validates a request and creates a run. Core stores the queue item and state in PostgreSQL, then a Worker claims it. Redis supports short-lived caching and distributed coordination; it is not the durable run queue. Starting only the API will not perform analysis.</p><p>Generated project documentation depends on a model channel. A channel is not one generic key in an env file. An administrator creates, tests, and enables it through the web app or API. The Worker resolves the selected channel and applies the run budget when it starts model work.</p><p>The first run must cover every active repository in the project. Incremental work becomes available only after that baseline succeeds. The API enforces this rule; do not bypass it by modifying database rows.</p><h2 id="what-retrieval-requires" tabindex="-1">What retrieval requires <a class="header-anchor" href="#what-retrieval-requires" aria-label="Permalink to &quot;What retrieval requires&quot;">​</a></h2><p>Lexical search reads the generated code index. Semantic search also requires Milvus and valid embedding settings. Hybrid search combines both result types.</p><p>Verify service startup and retrieval readiness separately:</p><ol><li>Confirm that Milvus is reachable.</li><li>Confirm that embedding configuration is valid.</li><li>Confirm that the project completed an analysis containing the search index.</li><li>Run a query with an explicit mode and inspect the effective mode and fallback reason in the response.</li></ol><p>Semantic mode does not silently return lexical results after an error. Hybrid mode can report an explicit fallback for supported failures, so clients should inspect response status instead of checking only whether results exist.</p><h2 id="what-access-and-automation-require" tabindex="-1">What access and automation require <a class="header-anchor" href="#what-access-and-automation-require" aria-label="Permalink to &quot;What access and automation require&quot;">​</a></h2><p>Web login uses the OPAQUE password flow and a session cookie. Browser requests that change state are also protected by CSRF and origin checks. MCP uses Bearer credentials with project scopes. Do not reuse credentials across those surfaces.</p><p>Remote repository credentials are stored with application-layer encryption. Use independent random values for repository encryption, sessions, MCP key hashing, and webhook signing. Read <a href="/en/configuration/security">Permissions and security</a> before rotating them because some changes invalidate stored data or active sessions.</p><p>Scheduled polling runs as a separate <code>ershu-api-poller</code> process. Webhooks are accepted by the API after it validates a signature over the timestamp, nonce, and raw body. Both paths create runs; a Worker is still required to execute them.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ol><li>Establish a startable environment with <a href="/en/configuration/basic">Basic configuration</a>.</li><li>Use <a href="/en/configuration/loading-and-overrides">Loading and overrides</a> to determine which value wins.</li><li>Prepare each process with <a href="/en/configuration/services">Service configuration</a>.</li><li>Look up types, defaults, and constraints in the <a href="/en/configuration/environment-reference">Environment reference</a>.</li><li>Complete <a href="/en/configuration/security">Permissions and security</a> before deployment.</li><li>Use <a href="/en/configuration/troubleshooting">Configuration troubleshooting</a> when startup fails.</li></ol><blockquote><p>Sources: settings types in all five modules, runtime-setting services, queue and analysis tests, search response contracts, and authentication and webhook security tests.</p></blockquote>',23)])])}const f=t(s,[["render",i]]);export{p as __pageData,f as default};
